// The lowest point in each post; posts with no point are NaN.
export function gridMin(points, bounds, spacing) {
  const width = Math.ceil((bounds.maxX - bounds.minX) / spacing) + 1;
  const height = Math.ceil((bounds.maxY - bounds.minY) / spacing) + 1;
  const values = new Float32Array(width * height).fill(NaN);
  for (const p of points) {
    const i = Math.round((bounds.maxY - p.y) / spacing) * width + Math.round((p.x - bounds.minX) / spacing);
    if (!(values[i] <= p.z)) values[i] = p.z;
  }
  return { width, height, values };
}

// Fills NaN posts with the mean of the valid ones. A grid with no valid post is returned as it is.
export function fillHoles(grid) {
  let sum = 0;
  let n = 0;
  for (const v of grid.values) if (Number.isFinite(v)) (sum += v), (n += 1);
  if (n === 0) return grid;
  return { ...grid, values: grid.values.map((v) => (Number.isFinite(v) ? v : sum / n)) };
}

