import { gridMin, fillHoles } from './grid.js';

// DTM from a point cloud: the lowest ground-classified point in each post, holes filled.
export function dtmFromPoints(cloud, spacing) {
  const ground = cloud.points.filter((p) => p.classification === 2);
  const grid = gridMin(ground, cloud.bounds, spacing);
  return fillHoles(grid);
}
